/**
 * Private staging and fixture subprocesses only: never deploys to a real target.
 */
class NativeUpdaterPushTest extends TestCase
{
    private string $root;
    private string $staging;

    /**
     * @return void
     */
    protected function setUp(): void
    {
        $this->root = NativeTestWorkspace::create('native-push');
        $this->staging = $this->root . DIRECTORY_SEPARATOR . 'private-staging';
        if (PHP_OS_FAMILY === 'Windows') {
            $script = '$ErrorActionPreference="Stop";$a=New-Object Security.AccessControl.DirectorySecurity;'
                . '$a.SetAccessRuleProtection($true,$false);'
                . '$r=New-Object Security.AccessControl.FileSystemAccessRule('
                . '[Security.Principal.WindowsIdentity]::GetCurrent().User,'
                . '"FullControl","ContainerInherit,ObjectInherit","None","Allow");$a.AddAccessRule($r);'
                . '[IO.Directory]::CreateDirectory($env:EXFACE_PUSH_FIXTURE_STAGING,$a)|Out-Null;';
            NativeBuildFiles::command('powershell.exe', ['-NoProfile', '-NonInteractive', '-EncodedCommand',
                base64_encode(implode("\0", str_split($script)) . "\0")], $this->root, 30,
                ['EXFACE_PUSH_FIXTURE_STAGING' => $this->staging]);
        } else {
            mkdir($this->staging, 0700);
        }
    }

    /**
     * @return void
     */
    protected function tearDown(): void
    {
        NativeBuildFiles::remove($this->root);
    }

    /**
     * @param string $body
     * @param string $id
     * @return ServerRequest
     */
    private function request(string $body, string $id = 'attempt-1'): ServerRequest
    {
        return new ServerRequest('POST', 'https://fixture.invalid/api/updater/native-push', [
            'Content-Type' => 'application/vnd.axenox.native-ota', 'Content-Length' => strlen($body),
            'X-Deployer-Deployment' => $id, 'X-Deployer-SHA256' => hash('sha256', $body),
            'X-Deployer-Filename' => 'ota-' . hash('sha256', $id) . '.phx'
        ], $body);
    }

    /**
     * Emits a receipt from a brand-new PHP runtime, not the test process.
     *
     * @param string $id
     * @param int $exit
     * @return string
     */
    private function fixture(string $id = 'attempt-1', int $exit = 0): string
    {
        return '<?php $f=fopen(getenv("EXFACE_NATIVE_OTA_RECEIPT"),"x+b");'
            . '$r=["protocol"=>"axenox.Deployer.native-ota/1","deployment_id"=>' . var_export($id, true)
            . ',"sha256"=>hash_file("sha256",__FILE__),"status"=>99];'
            . 'fwrite($f,json_encode($r));fclose($f);echo "sensitive-output-never-returned";exit(' . $exit . ');';
    }

    /**
     * @return void
     */
    public function testSubprocessReceiptVerifiedAndReplayNeverExecutesTwice(): void
    {
        $receiver = new NativePushReceiver($this->staging);
        $request = $this->request($this->fixture());
        $response = $receiver->receive($request);
        self::assertSame(200, $response->getStatusCode(), (string) $response->getBody());
        $receipt = json_decode((string) $response->getBody(), true);
        self::assertSame(99, $receipt['status']);
        self::assertSame($request->getHeaderLine('X-Deployer-SHA256'), $receipt['sha256']);
        self::assertStringNotContainsString('sensitive-output', (string) $response->getBody());
        self::assertSame(409, $receiver->receive($request)->getStatusCode());
        self::assertFileDoesNotExist($this->staging . DIRECTORY_SEPARATOR . hash('sha256', 'attempt-1')
            . DIRECTORY_SEPARATOR . 'package.phx');
    }

    /**
     * @return iterable
     */
    public static function failedPrograms(): iterable
    {
        yield 'stdout alone' => ['<?php echo "Installation successful! secret";'];
        yield 'invalid receipt' => ['<?php file_put_contents(getenv("EXFACE_NATIVE_OTA_RECEIPT"),"{\\"status\\":99}");'];
        yield 'empty receipt' => ['<?php touch(getenv("EXFACE_NATIVE_OTA_RECEIPT"));'];
    }

    /**
     * @dataProvider failedPrograms
     * @param string $program
     * @return void
     */
    public function testStdoutOrMissingReceiptNeverClaimsSuccess(string $program): void
    {
        $receiver = new NativePushReceiver($this->staging);
        $response = $receiver->receive($this->request($program));
        self::assertSame(500, $response->getStatusCode());
        self::assertSame(90, json_decode((string) $response->getBody(), true)['status']);
        self::assertStringNotContainsString('secret', (string) $response->getBody());
        self::assertFileExists($this->staging . DIRECTORY_SEPARATOR . hash('sha256', 'attempt-1')
            . DIRECTORY_SEPARATOR . 'package.phx');
    }

    /**
     * @return void
     */
    public function testMismatchedReceiptAndNonzeroExitFail(): void
    {
        $receiver = new NativePushReceiver($this->staging);
        self::assertSame(500, $receiver->receive($this->request($this->fixture('other')))->getStatusCode());
        self::assertSame(500, $receiver->receive($this->request($this->fixture('attempt-2', 9), 'attempt-2'))->getStatusCode());
    }

    /**
     * @return void
     */
    public function testLimitsHashAndHeadersFailBeforeExecution(): void
    {
        $receiver = new NativePushReceiver($this->staging, PHP_BINARY, 1024);
        $request = $this->request('<?php file_put_contents("executed","bad");');
        self::assertSame(400, $receiver->receive($request->withUri(new \GuzzleHttp\Psr7\Uri('http://fixture.invalid')))->getStatusCode());
        self::assertSame(400, $receiver->receive($request->withHeader('X-Deployer-Filename', '../bad.phx'))->getStatusCode());
        self::assertSame(400, $receiver->receive($request->withHeader('Content-Length', '1025'))->getStatusCode());
        self::assertSame(400, $receiver->receive($request->withHeader('X-Deployer-Deployment', '../attempt'))->getStatusCode());
        self::assertSame(500, $receiver->receive($request->withHeader('X-Deployer-SHA256', str_repeat('0', 64)))->getStatusCode());
        self::assertFileDoesNotExist($this->staging . DIRECTORY_SEPARATOR . hash('sha256', 'attempt-1')
            . DIRECTORY_SEPARATOR . 'executed');
    }

    /**
     * Packages a fixture application and invokes its new runtime over in-memory HTTP.
     *
     * @return void
     */
    public function testFullNativePushUsesStandaloneNewRuntimeAndKeepsSettings(): void
    {
        $source = $this->root . DIRECTORY_SEPARATOR . 'source';
        $target = $this->root . DIRECTORY_SEPARATOR . 'target';
        mkdir($source . DIRECTORY_SEPARATOR . 'builds', 0700, true);
        mkdir($source . DIRECTORY_SEPARATOR . 'vendor');
        mkdir($target);
        copy(dirname(__DIR__) . DIRECTORY_SEPARATOR . 'Fixtures' . DIRECTORY_SEPARATOR . 'NativeHostRuntime.php',
            $source . DIRECTORY_SEPARATOR . 'vendor' . DIRECTORY_SEPARATOR . 'autoload.php');
        file_put_contents($source . DIRECTORY_SEPARATOR . 'composer.json', '{"require":{}}');
        file_put_contents($source . DIRECTORY_SEPARATOR . 'fixture.json', '{"version":"v1","previous":null,"fail":false}');
        NativeBuildFiles::command('tar', ['-czf', $source . DIRECTORY_SEPARATOR . 'builds'
            . DIRECTORY_SEPARATOR . 'v1.tar.gz', '--', 'vendor', 'composer.json', 'fixture.json'], $source, 30);
        $receiver = new NativePushReceiver($this->staging);
        $connection = $this->getMockBuilder(HttpConnector::class)->disableOriginalConstructor()
            ->onlyMethods(['getUrl', 'sendRequest'])->getMock();
        $connection->method('getUrl')->willReturn('https://fixture.invalid');
        $connection->method('sendRequest')->willReturnCallback(function ($request) use ($receiver) {
            $incoming = new ServerRequest($request->getMethod(), $request->getUri(), $request->getHeaders(), $request->getBody());
            return $receiver->receive($incoming);
        });
        $pipeline = (new UpdaterPush($this->createStub(WorkbenchInterface::class)))
            ->setHostOperatingSystem(PHP_OS_FAMILY === 'Windows' ? 'Windows' : 'Linux')
            ->setHostPathToInstallationRoot($target)->setHostPhpExecutable(PHP_BINARY)
            ->setKeepReleases(7)->setConnection($connection);
        self::assertSame(7, $pipeline->exportUxonObject()->toArray()['keep_releases']);
        self::assertSame(['config'], $pipeline->exportUxonObject()->toArray()['copy_dirs']);
        $run = $pipeline->run(new ReleaseDeploymentTask('attempt-full', 'host', 'build', 'v1', $source));
        $log = implode('', iterator_to_array($run));
        self::assertSame(99, $run->getReturn()->getStatus(), $log);
        self::assertStringContainsString('independently verified', $log);
        self::assertCount(1, glob($source . DIRECTORY_SEPARATOR . '.native-deployments' . DIRECTORY_SEPARATOR . '*.phx'));
    }
